// Famous Chollima IT-worker scheme — RAT install on a recently-onboarded account + atypical AAD sign-in geo
let Lookback = 30d;
let NewAccountWindow = 30d;
let RatNames = dynamic(["anydesk.exe","anydeskmsi.exe","rustdesk.exe","remotedesktophost.exe","chromeremotedesktophost.exe","teamviewer_setup.exe","teamviewer.exe","meshagent.exe","meshcentral.exe"]);
let HighRiskGeos = dynamic(["CN","RU","KP","HK","BY","LA","VE"]);
let RatInstalls = DeviceProcessEvents
    | where Timestamp > ago(Lookback)
    | where FileName in~ (RatNames)
       or ProcessCommandLine has_any ("AnyDesk","RustDesk","chromeremotedesktop","MeshCentral","--install","--service","/silent")
    | where AccountName !endswith "$"
    | project InstallTime = Timestamp, DeviceName, DeviceId, AccountName, AccountUpn, RatImage = FileName, RatCmd = ProcessCommandLine;
let RecentAADSignIns = AADSignInEventsBeta
    | where Timestamp > ago(Lookback)
    | where ErrorCode == 0
    | where Country in~ (HighRiskGeos) or IsAnonymousProxy == true
    | project SignInTime = Timestamp, AccountUpn, IPAddress, Country, UserAgent, AppDisplayName;
let RecentHires = IdentityInfo
    | where isnotempty(AccountUpn)
    | summarize AccountAge = arg_max(Timestamp, *) by AccountUpn
    | extend IsNewHire = AccountAge > ago(NewAccountWindow);
RatInstalls
| join kind=inner RecentAADSignIns on AccountUpn
| where abs(datetime_diff('day', SignInTime, InstallTime)) <= 7
| join kind=leftouter RecentHires on AccountUpn
| project InstallTime, SignInTime, DeviceName, AccountUpn, RatImage, RatCmd, Country, IPAddress, UserAgent, AppDisplayName, IsNewHire
| order by InstallTime desc
